+package com.example;
+
+import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
+
+import java.util.List;
+import java.util.Map;
+
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+import org.springframework.boot.test.web.server.LocalServerPort;
+import org.vaadin.addons.dramafinder.element.ButtonElement;
+import org.vaadin.addons.dramafinder.element.EmailFieldElement;
+import org.vaadin.addons.dramafinder.element.GridElement;
+import org.vaadin.addons.dramafinder.element.TextAreaElement;
+import org.vaadin.addons.dramafinder.element.TextFieldElement;
+
+import com.microsoft.playwright.Browser;
+import com.microsoft.playwright.BrowserType;
+import com.microsoft.playwright.Page;
+import com.microsoft.playwright.Playwright;
+
+@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT,
+        properties = {"vaadin.launch-browser=false"})
+class ContactBrowserTest {
+    @LocalServerPort
+    private int port;
+
+    @Test
+    void contactFlowInChromium() {
+        try (Playwright playwright = Playwright.create(new Playwright.CreateOptions()
+                .setEnv(Map.of("PLAYWRIGHT_SKIP_BROWSER_DOWNLOAD", "1")));
+                Browser browser = playwright.chromium().launch(new BrowserType.LaunchOptions()
+                        .setHeadless(true).setArgs(List.of("--no-sandbox")))) {
+            Page page = browser.newPage();
+            page.navigate("http://localhost:" + port + "/contact");
+            assertThat(page.locator("h1")).hasText("Contact");
+            var name = TextFieldElement.getByLabel(page, "Name");
+            var email = EmailFieldElement.getByLabel(page, "Email");
+            var phone = TextFieldElement.getByLabel(page, "Phone");
+            var message = TextAreaElement.getByLabel(page, "Message");
+            var send = ButtonElement.getByText(page, "Send");
+            assertThat(send.getLocator()).isEnabled();
+            send.click();
+            name.assertErrorMessage("Name is required");
+            email.assertErrorMessage("Give an e-mail address or a phone number");
+            message.assertErrorMessage("Message is required");
+
+            page.getByLabel("Name", new Page.GetByLabelOptions().setExact(true)).fill("Browser sender");
+            page.getByLabel("Email", new Page.GetByLabelOptions().setExact(true)).fill("invalid");
+            page.getByLabel("Message", new Page.GetByLabelOptions().setExact(true)).fill("x".repeat(501));
+            send.click();
+            email.assertErrorMessage("Enter a valid e-mail address");
+            message.assertErrorMessage("Message must be at most 500 characters");
+            page.getByLabel("Email", new Page.GetByLabelOptions().setExact(true)).fill("");
+            page.getByLabel("Phone", new Page.GetByLabelOptions().setExact(true)).fill("555-1234");
+            page.getByLabel("Message", new Page.GetByLabelOptions().setExact(true)).fill("Browser message");
+            page.getByLabel("Message", new Page.GetByLabelOptions().setExact(true)).press("Enter");
+            assertThat(page.locator("vaadin-notification-card")).containsText("Message sent");
+            assertThat(send.getLocator()).isDisabled();
+            assertThat(page.getByLabel("Name", new Page.GetByLabelOptions().setExact(true))).isEmpty();
+            assertThat(page.getByLabel("Email", new Page.GetByLabelOptions().setExact(true))).isEmpty();
+            assertThat(page.getByLabel("Phone", new Page.GetByLabelOptions().setExact(true))).isEmpty();
+            assertThat(page.getByLabel("Message", new Page.GetByLabelOptions().setExact(true))).isEmpty();
+            GridElement.get(page).assertCellContent(0, 0, "Browser sender");
+            GridElement.get(page).assertCellContent(0, 1, "Browser message");
+
+            // A keystroke with no explicit blur must enable Send and protect navigation.
+            page.getByLabel("Phone", new Page.GetByLabelOptions().setExact(true)).fill("draft");
+            assertThat(send.getLocator()).isEnabled();
+            page.getByText("About", new Page.GetByTextOptions().setExact(true)).click();
+            assertThat(page.locator("vaadin-dialog-overlay")).isVisible();
+            ButtonElement.getByText(page, "Keep editing").click();
+            assertThat(page.locator("h1")).hasText("Contact");
+            assertThat(page.getByLabel("Phone", new Page.GetByLabelOptions().setExact(true))).hasValue("draft");
+            page.getByText("About", new Page.GetByTextOptions().setExact(true)).click();
+            ButtonElement.getByText(page, "Discard").click();
+            assertThat(page.locator("h1")).hasText("About");
+            page.goBack();
+            assertThat(page.locator("h1")).hasText("Contact");
+            GridElement.get(page).assertCellContent(0, 1, "Browser message");
+            page.getByText("About", new Page.GetByTextOptions().setExact(true)).click();
+            assertThat(page.locator("h1")).hasText("About");
+            assertThat(page.locator("vaadin-dialog-overlay")).hasCount(0);
+        }
+    }
+}
