+package com.example;
+
+import static org.junit.jupiter.api.Assertions.*;
+
+import org.junit.jupiter.api.BeforeEach;
+import org.junit.jupiter.api.Test;
+import org.junit.jupiter.params.ParameterizedTest;
+import org.junit.jupiter.params.provider.ValueSource;
+import org.springframework.boot.test.context.SpringBootTest;
+
+import com.vaadin.browserless.SpringBrowserlessTest;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.UI;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.router.RouterLink;
+
+@SpringBootTest
+class ContactViewTest extends SpringBrowserlessTest {
+    private TextField name;
+    private EmailField email;
+    private TextField phone;
+    private TextArea message;
+    private Button send;
+
+    @BeforeEach
+    void openContact() {
+        navigate(ContactView.class);
+        name = $(TextField.class).withLabel("Name").single();
+        email = $(EmailField.class).withLabel("Email").single();
+        phone = $(TextField.class).withLabel("Phone").single();
+        message = $(TextArea.class).withLabel("Message").single();
+        send = $(Button.class).withText("Send").single();
+    }
+
+    @Test
+    void emptyFormCanBeSubmittedAndReportsEveryRequiredField() {
+        assertEquals("Contact", $(H1.class).single().getText());
+        assertTrue(send.isEnabled());
+        assertTrue(name.isEmpty() && email.isEmpty() && phone.isEmpty() && message.isEmpty());
+        int before = rowCount();
+        test(send).click();
+        assertInvalid(name.isInvalid(), name.getErrorMessage(), "Name is required");
+        assertInvalid(email.isInvalid(), email.getErrorMessage(), "Give an e-mail address or a phone number");
+        assertInvalid(message.isInvalid(), message.getErrorMessage(), "Message is required");
+        assertFalse(phone.isInvalid());
+        assertTrue(send.isEnabled());
+        assertEquals(before, rowCount());
+        assertFalse($(Notification.class).exists());
+    }
+
+    @Test
+    void invalidValuesArePreservedAndCorrectable() {
+        test(name).setValue("  ");
+        test(email).setValue("invalid");
+        test(phone).setValue("123");
+        test(message).setValue("x".repeat(501));
+        int before = rowCount();
+        test(send).click();
+        assertInvalid(name.isInvalid(), name.getErrorMessage(), "Name is required");
+        assertInvalid(email.isInvalid(), email.getErrorMessage(), "Enter a valid e-mail address");
+        assertInvalid(message.isInvalid(), message.getErrorMessage(), "Message must be at most 500 characters");
+        assertEquals("invalid", email.getValue());
+        assertEquals(501, message.getValue().length());
+        assertEquals(before, rowCount());
+        assertFalse($(Notification.class).exists());
+        test(name).setValue("Ada");
+        test(email).setValue("ada@example.com");
+        test(message).setValue("x".repeat(500));
+        test(send).click();
+        assertEquals(before + 1, rowCount());
+        assertFalse(name.isInvalid() || email.isInvalid() || message.isInvalid());
+    }
+
+    @ParameterizedTest
+    @ValueSource(booleans = {true, false})
+    void eitherContactMethodWorksAndHistorySurvivesNavigation(boolean useEmail) {
+        int before = rowCount();
+        test(name).setValue("First sender");
+        if (useEmail) test(email).setValue("sender@example.com");
+        else test(phone).setValue("555-1234");
+        test(message).setValue("First message");
+        fireShortcut(Key.ENTER);
+        assertEquals(before + 1, rowCount());
+        assertTrue($(Notification.class).exists());
+        assertTrue(name.isEmpty() && email.isEmpty() && phone.isEmpty() && message.isEmpty());
+        assertFalse(send.isEnabled());
+        fireShortcut(Key.ENTER);
+        assertEquals(before + 1, rowCount());
+        test(name).setValue("Second sender");
+        assertTrue(send.isEnabled());
+        test(phone).setValue("123");
+        test(message).setValue("Second message");
+        test(send).click();
+        assertEquals("Second sender", test($(Grid.class).single()).getCellText(0, 0));
+        assertEquals("First message", test($(Grid.class).single()).getCellText(1, 1));
+        test($(RouterLink.class).withText("About").single()).click();
+        assertEquals("About", $(H1.class).single().getText());
+        assertFalse($(Dialog.class).exists());
+        navigate(ContactView.class);
+        assertEquals(before + 2, rowCount());
+        assertEquals("Second message", test($(Grid.class).single()).getCellText(0, 1));
+        assertTrue($(Button.class).withText("Send").single().isEnabled());
+    }
+
+    @ParameterizedTest
+    @ValueSource(strings = {"Name", "Email", "Phone", "Message"})
+    void everyFieldProtectsDraftsAndEnablesSendAfterSuccess(String field) {
+        test(name).setValue("Sent sender");
+        test(phone).setValue("123");
+        test(message).setValue("Sent text");
+        test(send).click();
+        assertFalse(send.isEnabled());
+        switch (field) {
+            case "Name" -> test(name).setValue("draft");
+            case "Email" -> test(email).setValue("draft");
+            case "Phone" -> test(phone).setValue("draft");
+            case "Message" -> test(message).setValue("draft");
+        }
+        assertTrue(send.isEnabled());
+        // Programmatic navigation must be protected just like a RouterLink.
+        UI.getCurrent().navigate(AboutView.class);
+        assertInstanceOf(ContactView.class, getCurrentView());
+        assertTrue($(Dialog.class).single().isOpened());
+        test($(Button.class).withText("Keep editing").single()).click();
+        assertInstanceOf(ContactView.class, getCurrentView());
+        assertEquals("draft", switch (field) {
+            case "Name" -> name.getValue();
+            case "Email" -> email.getValue();
+            case "Phone" -> phone.getValue();
+            default -> message.getValue();
+        });
+        test($(RouterLink.class).single()).click();
+        test($(Button.class).withText("Discard").single()).click();
+        assertInstanceOf(AboutView.class, getCurrentView());
+    }
+
+    @Test
+    void clearedDraftDoesNotInterruptNavigation() {
+        test(name).setValue("draft");
+        test(name).clear();
+        test($(RouterLink.class).single()).click();
+        assertInstanceOf(AboutView.class, getCurrentView());
+        assertFalse($(Dialog.class).exists());
+    }
+
+    private int rowCount() {
+        return test($(Grid.class).single()).size();
+    }
+
+    private static void assertInvalid(boolean invalid, String actual, String expected) {
+        assertTrue(invalid);
+        assertEquals(expected, actual);
+    }
+}
